// content.js — openOptionsPage is unavailable in content scripts,
// so delegate to the service worker via runtime messaging.
function openOptionsPage() {
  try {
    chrome.runtime.sendMessage({ type: 'OPEN_OPTIONS' }, () => {
      if (chrome.runtime.lastError) {
        console.warn('[aaw] openOptionsPage failed:', chrome.runtime.lastError.message);
      }
    });
  } catch (err) {
    console.warn('[aaw] openOptionsPage threw:', err && err.message);
  }
}

// app/Providers/AppServiceProvider.php
$this->app->singleton(PaymentGateway::class, function () {
    $driver = config('payment.driver', 'fake');

    return match ($driver) {
        'stripe' => new StripePaymentGateway(
            new StripeClient((string) config('payment.stripe.secret'))
        ),
        default => new FakePaymentGateway(),   // clone and run, no keys
    };
});

// src/ErrorMonitoring.Infrastructure/Data/AppDbContext.cs
modelBuilder.Entity<LogEntry>(entity =>
{
    entity.Property(e => e.Severity).HasConversion<string>();

    // The dashboard filters a time range and sorts by Timestamp desc.
    // One composite seek beats two single-column indexes here because
    // it satisfies the filter and the ordering in the same pass.
    entity.HasIndex(e => new { e.Timestamp, e.Severity })
          .HasDatabaseName("IX_LogEntries_Timestamp_Severity");
});
